// Text from the web, tools and workspace is untrusted terminal input. Drop
// terminal commands, including incomplete sequences in a streaming snapshot,
// before applying any styling generated by the harness itself.
export function terminalText(input: string): string {
  let output = "";
  let state: "text" | "escape" | "csi" | "string" | "string-escape" = "text";
  const text = input.replace(/\r\n?/g, "\n");

  for (const char of text) {
    const code = char.codePointAt(0)!;
    if (state === "string") {
      if (code === 0x07 || code === 0x9c) state = "text";
      else if (code === 0x1b) state = "string-escape";
      continue;
    }
    if (state === "string-escape") {
      if (char === "\\" || code === 0x9c || code === 0x07) state = "text";
      else if (code !== 0x1b) state = "string";
      continue;
    }
    if (state === "csi") {
      if (code >= 0x40 && code <= 0x7e) state = "text";
      else if (code === 0x1b) state = "escape";
      continue;
    }
    if (state === "escape") {
      if (char === "[") state = "csi";
      else if (char === "]" || char === "P" || char === "X" || char === "^" || char === "_") state = "string";
      else if (code >= 0x20 && code <= 0x2f) { /* escape intermediate */ }
      else if (code !== 0x1b) state = "text";
      continue;
    }
    if (code === 0x1b) state = "escape";
    else if (code === 0x9b) state = "csi";
    else if (code === 0x90 || code === 0x98 || code === 0x9d || code === 0x9e || code === 0x9f) state = "string";
    else if (char === "\n") output += char;
    else if (char === "\t") output += "    ";
    else if (code >= 0x20 && code !== 0x7f && !(code >= 0x80 && code <= 0x9f)) output += char;
  }
  return output;
}
